import React from 'react';
import {
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import type { ImportClarificationRequest } from './accountingImportResult';

interface ImportFileDecisionDialogsProps {
  clarification: ImportClarificationRequest | null;
  clarificationIndex: number;
  clarificationCount: number;
  clarificationText: string;
  clarificationQuantity: string;
  clarificationUnit: string;
  originAirport: string;
  destinationAirport: string;
  onClarificationText: (value: string) => void;
  onClarificationQuantity: (value: string) => void;
  onClarificationUnit: (value: string) => void;
  onOriginAirport: (value: string) => void;
  onDestinationAirport: (value: string) => void;
  onSaveClarification: () => void;
  onDismissClarification: () => void;
  decisionOpen: boolean;
  fileName: string;
  importedCount: number;
  deciding: boolean;
  onConfirmFile: () => void;
  onRejectFile: () => void;
  onDismissDecision: () => void;
}

const ImportFileDecisionDialogs: React.FC<ImportFileDecisionDialogsProps> = ({
  clarification,
  clarificationIndex,
  clarificationCount,
  clarificationText,
  clarificationQuantity,
  clarificationUnit,
  originAirport,
  destinationAirport,
  onClarificationText,
  onClarificationQuantity,
  onClarificationUnit,
  onOriginAirport,
  onDestinationAirport,
  onSaveClarification,
  onDismissClarification,
  decisionOpen,
  fileName,
  importedCount,
  deciding,
  onConfirmFile,
  onRejectFile,
  onDismissDecision,
}) => (
  <>
    <Dialog
      open={Boolean(clarification)}
      onClose={onDismissClarification}
      aria-labelledby="import-clarification-title"
      fullWidth
      maxWidth="sm"
    >
      <DialogTitle id="import-clarification-title">
        {clarification?.title || 'Clarify this transaction'}
      </DialogTitle>
      <DialogContent>
        <Stack spacing={1.5} sx={{ pt: 0.5 }}>
          <Typography variant="body2" color="text.secondary">
            {clarificationCount > 1
              ? `Transaction ${clarificationIndex + 1} of ${clarificationCount}. Carbon calculation waits until you confirm the file.`
              : 'Carbon calculation waits until you confirm the file.'}
          </Typography>
          {clarification?.description && (
            <Typography variant="body2">{clarification.description}</Typography>
          )}
          {clarification?.helper && (
            <Typography variant="body2">{clarification.helper}</Typography>
          )}
          {clarification?.example && (
            <Typography variant="body2" color="text.secondary">
              {`Example: ${clarification.example}`}
            </Typography>
          )}
          <TextField
            label={clarification?.question || 'What is this transaction?'}
            value={clarificationText}
            onChange={(event) => onClarificationText(event.target.value)}
            placeholder={clarification?.example || ''}
            fullWidth
            multiline
            minRows={2}
            autoFocus
          />
          <TextField
            label="Quantity"
            value={clarificationQuantity}
            onChange={(event) => onClarificationQuantity(event.target.value)}
            type="number"
            fullWidth
          />
          <TextField
            label="Unit"
            value={clarificationUnit}
            onChange={(event) => onClarificationUnit(event.target.value)}
            fullWidth
            placeholder={(clarification?.unitOptions || []).join(', ')}
          />
          {clarification?.requireAirports && (
            <Stack direction="row" spacing={1}>
              <TextField
                label="Origin airport"
                value={originAirport}
                onChange={(event) => onOriginAirport(event.target.value)}
                placeholder="BLR"
                fullWidth
              />
              <TextField
                label="Destination airport"
                value={destinationAirport}
                onChange={(event) => onDestinationAirport(event.target.value)}
                placeholder="DEL"
                fullWidth
              />
            </Stack>
          )}
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button onClick={onDismissClarification} disabled={deciding}>Close</Button>
        <Button variant="contained" onClick={onSaveClarification} disabled={deciding}>
          Save clarification
        </Button>
      </DialogActions>
    </Dialog>

    <Dialog
      open={decisionOpen}
      onClose={onDismissDecision}
      aria-labelledby="import-file-decision-title"
      fullWidth
      maxWidth="sm"
    >
      <DialogTitle id="import-file-decision-title">Confirm or reject this input file</DialogTitle>
      <DialogContent>
        <Stack spacing={1.25} sx={{ pt: 0.5 }}>
          <Typography variant="body1" sx={{ fontWeight: 600 }}>
            {fileName}
          </Typography>
          <Typography variant="body2">
            {importedCount} transaction{importedCount === 1 ? '' : 's'} {importedCount === 1 ? 'is' : 'are'} ready.
            Confirm to calculate carbon for this file. Reject to drop the file.
          </Typography>
        </Stack>
      </DialogContent>
      <DialogActions>
        <Button color="error" onClick={onRejectFile} disabled={deciding}>
          Reject file
        </Button>
        <Button variant="contained" color="success" onClick={onConfirmFile} disabled={deciding}>
          Confirm file
        </Button>
      </DialogActions>
    </Dialog>
  </>
);

export default ImportFileDecisionDialogs;
