/**
 * What to ask for when a row is still an estimate or miscellaneous calculation.
 * Web copy of shared/missingCarbonInputs.js. Keep the two files in sync.
 */
import { isEstimateOrMiscellaneousTransaction } from './estimateScreeningPolicy';
import { SCOPE3_GAP_IDS, scope3BillPrompt } from './scope3BillRequests';

const ACTIVITY_GAP_IDS = new Set([
  'flight_requires_origin_destination',
  'cat4_requires_tonne_km',
  'cat9_requires_tonne_km',
  'cat6_requires_room_nights',
  'cat6_requires_passenger_km',
  'cat7_requires_commute_km',
  'cat7_wfh_requires_hours_or_kwh',
  'bus_requires_passenger_km',
  'courier_requires_parcel_kg',
  'cat8_requires_energy_data',
  'cat10_requires_processing_data',
  'cat11_requires_use_phase_data',
  'cat12_requires_eol_activity',
  'cat13_requires_energy_data',
  'cat14_requires_franchisee_inventory',
  'cat15_requires_investee_emissions',
  'electricity_requires_bill_quantity',
  'electricity_quantity_amount_mismatch',
  ...SCOPE3_GAP_IDS
]);

const activityAsk = (unit, quantityLabel, helper, extras = {}) => ({
  unit,
  quantityLabel,
  unitOptions: extras.unitOptions || [unit],
  helper,
  requireMaterialName: extras.requireMaterialName === true,
  requireAirports: extras.requireAirports === true,
  scope3Gap: extras.scope3Gap || null,
  extraFields: Array.isArray(extras.extraFields) ? extras.extraFields : [],
  primaryKgField: extras.primaryKgField || null
});

const spendAsk = (kind, metadataField, label, helper) => ({
  kind,
  metadataField,
  label,
  helper
});

const textOf = (transaction = {}) => [
  transaction.category,
  transaction.subcategory,
  transaction.description,
  transaction.carbonFootprint?.factorLineage?.id
].join(' ').toLowerCase();

const hasActivityGap = (transaction = {}) => {
  const footprint = transaction.carbonFootprint || {};
  const ids = [
    footprint.scope3ActivityGap,
    footprint.factorLineage && footprint.factorLineage.id,
    ...(Array.isArray(footprint.complianceFlags) ? footprint.complianceFlags : [])
  ];
  return ids.some((id) => ACTIVITY_GAP_IDS.has(String(id || '')));
};

const MEASURED_ACTIVITY = /(\d+(?:\.\d+)?)\s*(?:kwh|kw-h|litres|liters|litre|liter|ltr|kg|tonne-km|ton-km|tonkm|passenger-km|passenger km|pax-km|gb|m3|m³|nights?|hours?|km)\b/i;

const NAMED_ACTIVITY = /\b(?:electricity|power bill|discom|bescom|diesel|petrol|lpg|cng|fuel|coal|furnace|freight|courier|parcel|hotel|lodging|accommodation|flight|airline|air travel|air ticket|airfare|air fare|water|sewage|wastewater|waste|steel|cement|clinker|plastic|paper|maintenance|telecom|commut|taxi|cab|bus|rail|two-wheeler|scooter|motorcycle|refrigerant|work from home|wfh|homeworking|home-working)\b/i;

const AIRPORT_STOPWORDS = new Set([
  'AND', 'THE', 'FOR', 'GST', 'INR', 'AMC', 'LPG', 'CNG', 'EV'
]);

const ACTIVITY_FAMILIES = [
  ['flight', /\b(flight|air india|airline|air travel|air ticket|airfare)\b/i],
  ['hotel', /\b(hotel|lodging|room nights|accommodation)\b/i],
  ['shuttle', /\bshuttle\b/i],
  ['commute', /\bcommut/i],
  ['maintenance', /\b(maintenance|amc\b|refrigerant)\b/i],
  ['coating', /\b(coating|paint)\b/i],
  ['cooling', /\b(cooling|chilled[- ]water)\b/i],
  ['steam', /\b(steam|district heat|thermal energy)\b/i],
  ['electricity', /\b(electricity|solar|energy use|energy consumption|kwh)\b/i],
  ['fuel', /\b(diesel|petrol|cng|lpg|coal|furnace oil|natural gas|furnace)\b/i],
  ['water', /\b(water|sewage|wastewater|effluent)\b/i],
  ['waste', /\b(solid waste|end-of-life|take-back|boiler ash)\b/i],
  ['material', /\b(steel|plastic|polymer|paper|resin|paperboard)\b/i],
  ['equipment', /\b(compressor|inspection station|variable-speed|capital goods)\b/i],
  ['transport', /\b(supplier truck|customer delivery|freight)\b/i],
  ['processing', /\b(job work|processing of sold)\b/i],
  ['use', /\buse phase\b/i],
  ['lease', /\b(lease of|leased)\b/i]
];

const transactionNarrative = (transaction = {}) => [
  transaction.description,
  transaction.memo,
  transaction.narration
].map((part) => String(part || '').trim()).filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();

const activityFamily = (clause = '') => {
  const hit = ACTIVITY_FAMILIES.find(([, pattern]) => pattern.test(clause));
  return hit ? hit[0] : null;
};

const compositeActivities = (text = '') => {
  const parts = String(text).split(/\s+and\s+/i);
  if (parts.length >= 2 && parts[0].trim().split(/\s+/).length >= 3) {
    const left = activityFamily(parts[0]);
    const right = activityFamily(parts.slice(1).join(' and '));
    if (left && right && left !== right) return [left, right];
  }
  if (/\b(delivered by|customer delivery|delivered \d+(?:\.\d+)?\s*km)\b/i.test(text)) {
    const carried = activityFamily(String(text).replace(/\b(delivered by|customer delivery|delivered \d+(?:\.\d+)?\s*km)\b/ig, ' '));
    if (carried && carried !== 'transport') return [carried, 'transport'];
  }
  return null;
};

const hasAirportPair = (text = '') => {
  const codes = String(text).toUpperCase().match(/\b[A-Z]{3}\b/g) || [];
  return codes.filter((code) => !AIRPORT_STOPWORDS.has(code)).length >= 2;
};

const hasDistance = (text = '') => /\d+(?:\.\d+)?\s*(?:km|kilometres|kilometers)\b/i.test(text);

const hasFuelOrEv = (text = '') => /\b(diesel|petrol|cng|lpg|ev|electric)\b/i.test(text);

const hasPassengerMode = (text = '') => (
  /\b(car|bus|rail|train|two-wheeler|scooter|motorcycle|cab|taxi|metro|ev|electric|diesel|petrol|cng)\b/i.test(text)
);

const maintenanceIsSpecific = (text = '') => {
  const hasQuantity = /\d+(?:\.\d+)?\s*(?:visits?|jobs?|service units?|kg|litres|liters|ltr)\b/i.test(text);
  const hasSystem = /\b(chiller|compressor|boiler|refrigerant|hvac|generator|pump|furnace)\b/i.test(text);
  return hasQuantity && hasSystem;
};

/**
 * Cases where a taxonomy label is not enough to calculate carbon.
 * The classifier may still store one category. Calculation waits for this text.
 */
export const classifierUncertainty = (transaction = {}) => {
  if (transaction.metadata && transaction.metadata.descriptionClarifiedWithoutBill) return null;
  const text = transactionNarrative(transaction);
  if (!text) return null;
  const meta = transaction.metadata || {};

  const mixed = compositeActivities(text);
  if (mixed) {
    return {
      id: 'composite_activities',
      title: 'This voucher mixes more than one activity',
      activity: activityAsk(
        'kg',
        'Quantity of the main activity',
        'List each activity and its quantity. The calculation uses only what you confirm.',
        { unitOptions: ['kg', 'kWh', 'L', 'km', 'tonne-km', 'service_unit'], requireMaterialName: true }
      ),
      clarification: {
        title: 'This voucher mixes more than one activity',
        helper: `The description names ${mixed[0]} and ${mixed[1]}. A single category would drop one of them. List each activity and its quantity before the carbon calculation continues.`,
        question: 'List each activity and its quantity',
        example: 'Steel coil 2 tonne and supplier truck delivery 80 km'
      }
    };
  }

  if (/\b(flight|air india|airline|air travel|air ticket|airfare)\b/i.test(text)) {
    const airportsKnown = (meta.originAirport && meta.destinationAirport) || hasAirportPair(text);
    if (!airportsKnown) {
      return {
        id: 'air_route_missing',
        title: 'Add the flight airports',
        activity: activityAsk(
          'passenger',
          'Passengers',
          'Enter the origin and destination airport codes. The route calculation needs both.',
          { unitOptions: ['passenger', 'km', 'passenger-km'], requireAirports: true }
        ),
        clarification: {
          title: 'Add the flight airports',
          helper: 'This flight does not name the origin and destination airports. Enter both codes, for example BLR and DEL, before the carbon calculation continues.',
        question: 'Origin and destination airports',
        example: 'Air India flight BLR to DEL, 1 passenger'
      }
      };
    }
  }

  if (/\bshuttle\b/i.test(text) && (!hasFuelOrEv(text) || !hasDistance(text))) {
    return {
      id: 'shuttle_details_missing',
      title: 'Add the shuttle fuel and distance',
      activity: activityAsk(
        'km',
        'Kilometres',
        'Say whether the shuttle uses diesel, petrol, CNG, or is an EV, and enter the kilometres.',
        { unitOptions: ['km', 'passenger-km'] }
      ),
      clarification: {
        title: 'Add the shuttle fuel and distance',
        helper: 'The shuttle description does not say the fuel, whether the vehicle is an EV, and how many kilometres it ran. Add those before the carbon calculation continues.',
        question: 'Fuel or EV, and how many kilometres?',
        example: 'CNG shuttle, 40 km'
      }
    };
  }

  if (/\bcommut/i.test(text) && (!hasPassengerMode(text) || !hasDistance(text))) {
    return {
      id: 'commute_details_missing',
      title: 'Add the commute mode and distance',
      activity: activityAsk(
        'passenger-km',
        'Passenger-kilometres',
        'Name how passengers travel and enter the kilometres.',
        { unitOptions: ['passenger-km', 'km'] }
      ),
      clarification: {
        title: 'Add the commute mode and distance',
        helper: 'Passenger commute is not clear enough to calculate. Name the mode, the fuel or EV, and the kilometres before the carbon calculation continues.',
        question: 'How do passengers commute, and how many kilometres?',
        example: 'Two-wheeler commute, 120 km'
      }
    };
  }

  if (/\b(maintenance|amc\b)\b/i.test(text) && !maintenanceIsSpecific(text)) {
    return {
      id: 'maintenance_details_missing',
      title: 'Add what this maintenance bill covers',
      activity: activityAsk(
        'service_unit',
        'Visits or jobs',
        'Name the equipment or refrigerant and enter the visits or the quantity.',
        { unitOptions: ['service_unit', 'visit', 'job', 'kg'], requireMaterialName: true }
      ),
      clarification: {
        title: 'Add what this maintenance bill covers',
        helper: 'A maintenance bill can be a service visit, spare parts, or a refrigerant loss. Name the equipment and the quantity before the carbon calculation continues.',
        question: 'What equipment or refrigerant, and what quantity?',
        example: 'Chiller AMC, 2 visits'
      }
    };
  }

  return null;
};

const descriptionIsUncertain = (transaction = {}) => {
  const text = [transaction.description, transaction.memo, transaction.narration]
    .map((part) => String(part || '').trim())
    .filter(Boolean)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (!text) return true;
  if (MEASURED_ACTIVITY.test(text)) return false;
  if (NAMED_ACTIVITY.test(text)) return false;
  return true;
};

const genericClarification = () => ({
  title: 'Clarify this transaction',
  helper: 'The description does not say what this transaction is. Upload the bill so the activity can be read from it. If the bill is not uploaded, name the activity and enter the quantity.',
  question: 'What is this transaction?',
  example: 'Diesel for the DG set, 200 L'
});

const attachDescriptionClarification = (transaction, prompt) => {
  const uncertainty = classifierUncertainty(transaction);
  if (!prompt && !uncertainty) return null;
  if (uncertainty) {
    const base = prompt || {
      title: uncertainty.title,
      activity: uncertainty.activity,
      spend: null
    };
    return {
      ...base,
      title: uncertainty.title,
      activity: uncertainty.activity || base.activity,
      descriptionUncertain: true,
      clarificationDirect: true,
      clarification: uncertainty.clarification
    };
  }
  if (!descriptionIsUncertain(transaction)) {
    return { ...prompt, descriptionUncertain: false, clarification: null, clarificationDirect: false };
  }
  return {
    ...prompt,
    descriptionUncertain: true,
    clarificationDirect: false,
    clarification: genericClarification()
  };
};

const buildMissingCarbonInput = (transaction = {}) => {
  if (!isEstimateOrMiscellaneousTransaction(transaction).match && !hasActivityGap(transaction)) {
    return null;
  }

  const scope3Prompt = scope3BillPrompt(transaction);
  if (scope3Prompt) return scope3Prompt;

  const category = String(transaction.category || '').toLowerCase();
  const factorId = String(transaction.carbonFootprint?.factorLineage?.id || '');
  const text = textOf(transaction);

  if (/\b(flight|airline|air ticket|air travel|airfare|air fare)\b/.test(text) || String(transaction.subcategory || '').toLowerCase() === 'air_travel') {
    return {
      title: 'Add the flight route from the bill',
      activity: activityAsk(
        'passenger',
        'Passengers',
        'Upload the ticket and enter the origin and destination airport codes. That uses the ICAO route calculation. If the ticket only shows distance, enter kilometres. That uses the DESNZ 2025 international flight factor, 0.0842 kg CO2e per passenger-km. A ticket with neither stays at 0.',
        { unitOptions: ['km', 'passenger-km', 'passenger'], requireAirports: true }
      ),
      spend: null
    };
  }

  if (/\b(hotel|lodging|accommodation)\b/.test(text)) {
    return {
      title: 'Add hotel nights from the bill',
      activity: activityAsk(
        'night',
        'Room-nights',
        'Enter room-nights from the hotel bill. India stays use 58.9 kgCO2e per room-night. A stay named outside India stays at 0 kg.'
      ),
      spend: null
    };
  }

  if (/\b(work from home|wfh|remote work|homeworking)\b/.test(text)) {
    return {
      title: 'Add home-working electricity from the bill',
      activity: activityAsk(
        'kWh',
        'kWh',
        'Enter kWh from the bill. That uses the CEA grid factor and enters the inventory. Hours alone stay at 0.',
        { unitOptions: ['kWh', 'hour'] }
      ),
      spend: null
    };
  }

  const miscellaneous = factorId === 'spend_generic' || category === 'other';

  if (miscellaneous) {
    return {
      title: 'Add the activity this purchase covers',
      activity: activityAsk(
        'kg',
        'Quantity',
        'Name the material or activity and enter its quantity. That replaces the miscellaneous factor with an activity-based calculation.',
        {
          unitOptions: ['kg', 'kWh', 'L', 'tonne-km', 'service_unit'],
          requireMaterialName: true
        }
      ),
      spend: null
    };
  }

  if (
    category === 'water'
    || ['water_consumption', 'sewage_disposal', 'wastewater_treatment'].includes(factorId)
  ) {
    return {
      title: 'Add water activity or a water unit price',
      activity: activityAsk(
        'L',
        'Litres',
        'Enter litres for an activity-based calculation.'
      ),
      spend: spendAsk(
        'water',
        'waterUnitPriceInr',
        '₹ per litre',
        'Enter the bill ₹ per litre for a spend-based calculation.'
      )
    };
  }

  if (category === 'maintenance' || factorId === 'maintenance_service_unit') {
    return {
      title: 'Add maintenance jobs or a job rate',
      activity: activityAsk(
        'service_unit',
        'Jobs or visits',
        'Enter the number of jobs. Unit service_unit, visit, or job is an activity-based calculation.',
        { unitOptions: ['service_unit', 'visit', 'job'] }
      ),
      spend: spendAsk(
        'maintenance',
        'maintenanceUnitPriceInr',
        '₹ per service unit',
        'Enter the ₹ cost of one job for a spend-based calculation.'
      )
    };
  }

  if (category === 'waste_management') {
    return {
      title: 'Add waste mass or a waste unit price',
      activity: activityAsk('kg', 'Kilograms', 'Enter kilograms for an activity-based calculation.'),
      spend: spendAsk(
        'waste',
        'wasteUnitCostInr',
        '₹ per kg',
        'Enter ₹ per kg for a spend-based calculation.'
      )
    };
  }

  if (category === 'equipment') {
    return {
      title: 'Add equipment mass',
      activity: activityAsk('kg', 'Kilograms', 'Enter kilograms for an activity-based calculation.'),
      spend: null
    };
  }

  if (category === 'telecom') {
    return {
      title: 'Add data use',
      activity: activityAsk('GB', 'Gigabytes', 'Enter gigabytes for an activity-based calculation.'),
      spend: null
    };
  }

  if (category === 'transportation' || category === 'travel') {
    if (/\b(courier|parcel|dtdc|bluedart|delhivery)\b/.test(text)) {
      return {
        title: 'Add parcel weight',
        activity: activityAsk('kg', 'Kilograms', 'Enter parcel kilograms for an activity-based calculation.'),
        spend: null
      };
    }
    if (/\bbus\b/.test(text)) {
      return {
        title: 'Add passenger-kilometres from the bill',
        activity: activityAsk(
          'passenger-km',
          'Passenger-kilometres',
          'The bus factor is per passenger-km. Upload the bill and enter passenger-kilometres. Vehicle kilometres stay at 0.'
        ),
        spend: null
      };
    }
    if (/\b(cab|taxi|rail|commut|passenger)\b/.test(text)) {
      return {
        title: 'Add distance from the bill',
        activity: activityAsk(
          'km',
          'Kilometres',
          'Enter kilometres from the bill for an activity-based calculation.',
          { unitOptions: ['km', 'passenger-km'] }
        ),
        spend: null
      };
    }
    return {
      title: 'Add freight activity',
      activity: activityAsk(
        'tonne-km',
        'Tonne-kilometres',
        'Enter tonne-km for an activity-based calculation. A rupee amount is not a freight factor.'
      ),
      spend: null
    };
  }

  if (category === 'raw_materials') {
    return {
      title: 'Add material mass',
      activity: activityAsk(
        'kg',
        'Kilograms',
        'Enter kilograms for an activity-based calculation.',
        { requireMaterialName: factorId === 'spend_generic' }
      ),
      spend: null
    };
  }

  const flags = Array.isArray(transaction.carbonFootprint?.complianceFlags)
    ? transaction.carbonFootprint.complianceFlags.map((flag) => String(flag))
    : [];
  if (flags.includes('electricity_quantity_amount_mismatch')) {
    return {
      title: 'Electricity quantity does not match the amount',
      activity: activityAsk(
        'kWh',
        'kWh',
        'The electricity quantity does not match the rupee amount. Upload the electricity bill so the quantity and unit can be verified before carbon is calculated.'
      ),
      spend: null
    };
  }

  const fuel = /\b(diesel|petrol|lpg|cng|fuel|coal|natural gas|furnace)\b/.test(text)
    || factorId.startsWith('fuel_');
  if (category === 'energy' || category === 'utilities' || fuel) {
    if (fuel && !/\b(kwh|electricity|discom|power bill)\b/.test(text)) {
      return {
        title: 'Add fuel quantity or a fuel unit price',
        activity: activityAsk(
          'L',
          'Litres',
          'Enter litres for an activity-based calculation.',
          { unitOptions: ['L', 'kg', 'm3'] }
        ),
        spend: spendAsk(
          'fuel',
          'fuelUnitPriceInr',
          '₹ per litre',
          'Enter ₹ per litre for a spend-based calculation.'
        )
      };
    }
    return {
      title: 'Upload the electricity bill',
      activity: activityAsk(
        'kWh',
        'kWh',
        'Upload the electricity bill and enter the metered quantity and unit (kWh). A rupee amount is not used to estimate kilowatt-hours.'
      ),
      spend: null
    };
  }

  return {
    title: 'Add the missing activity',
    activity: activityAsk(
      'kg',
      'Quantity',
      'Enter a quantity and unit for an activity-based calculation.',
      { unitOptions: ['kg', 'kWh', 'L', 'tonne-km', 'service_unit'] }
    ),
    spend: null
  };
};

export const resolveMissingCarbonInput = (transaction = {}) => (
  attachDescriptionClarification(transaction, buildMissingCarbonInput(transaction))
);
