import type { OcrValidation } from '../components/OCRValidationBanner';
import type { Document } from '../services/documentService';

type DocumentWithProcessing = Pick<
  Document,
  'status' | 'processingResults' | 'ocrValidation' | 'metadata'
>;

const OCR_QUALITY_MESSAGE_PATTERN =
  /blurry|not clear|clearer|clear image|unable to read|cannot read|difficult to read|characters|illegible|too faint|extraction quality is|minimum \d+%/i;

export function getDocumentProcessingErrorMessage(document: DocumentWithProcessing): string | null {
  if (document.status !== 'failed') {
    return null;
  }
  const errors = document.processingResults?.errors;
  if (!errors?.length) {
    return null;
  }
  const first = errors.find((entry) => typeof entry === 'string' && entry.trim());
  return first ? first.trim() : null;
}

export function isBillQualityProcessingFailure(document: DocumentWithProcessing): boolean {
  const validation =
    document.processingResults?.ocrValidation || document.ocrValidation || null;
  if (validation?.gate_rejection_reason === 'bill_quality_below_threshold') {
    return true;
  }
  const metadataReason = document.metadata?.ocr?.gateRejectionReason
    || document.metadata?.ocr?.rejectionReason;
  return metadataReason === 'bill_quality_below_threshold';
}

export function isOcrQualityProcessingFailure(document: DocumentWithProcessing): boolean {
  if (isBillQualityProcessingFailure(document)) {
    return true;
  }
  const message = getDocumentProcessingErrorMessage(document);
  if (message && OCR_QUALITY_MESSAGE_PATTERN.test(message)) {
    return true;
  }
  const validation =
    document.processingResults?.ocrValidation || document.ocrValidation || null;
  return Boolean(validation?.unreadable && validation?.user_action?.message);
}

export function getOcrValidationFromDocument(document: DocumentWithProcessing): OcrValidation | null {
  return (
    (document.ocrValidation as OcrValidation | null | undefined) ||
    (document.processingResults?.ocrValidation as OcrValidation | null | undefined) ||
    null
  );
}
